ROOT=Path(__file__).resolve().parents[1]; sys.path.insert(0,str(ROOT))
from scripts.verify_experiment_d_frozen_baseline import build_manifest as frozen_baseline
from src.experiment_d.integrity import sha256_file
OUT=ROOT/"reports/experiment_e/analysis/e8_final_comparison.json"; AUDIT=ROOT/"reports/experiment_e/audit/e8_scientific_decision.json"
FILES={"e3_extraction":"reports/experiment_e/audit/e3_extraction_validation_final.json","e3_distribution":"reports/experiment_e/analysis/e3_distribution_analysis.json","e4":"reports/experiment_e/audit/e4_dataset_construction_audit.json","e5":"reports/experiment_e/audit/e5_training_audit.json","e6":"reports/experiment_e/evaluation/e6_offline_validation.json","e7":"reports/experiment_e/runtime_validation/e7_runtime_validation.json","candidate":"models/experiment_e/random_forest_rf_v3_candidate.joblib","candidate_metadata":"models/experiment_e/random_forest_rf_v3_candidate_metadata.json","rf_v2_frozen":"reports/experiment_d/audit/rf_v2_frozen_manifest.json","final_test_seal":"reports/experiment_d/audit/final_test_leakage_audit.json"}
def write_new(p,x):
    if p.exists(): raise FileExistsError(p)
    p.parent.mkdir(parents=True,exist_ok=True); p.write_text(json.dumps(x,indent=2,sort_keys=True)+"\n")
def m(r,c): return r["observed_class_metrics"][c]
def main():
    if OUT.exists() or AUDIT.exists(): raise FileExistsError("E8 create-new outputs already exist")
    evidence={k:{"path":v,"sha256":sha256_file(ROOT/v)} for k,v in FILES.items()}
    if evidence["candidate"]["sha256"]!="6b01c7b3923c1a6bd471862d011f8f5b88a31378e51d1dde082bd2e72bedef86": raise ValueError("candidate hash mismatch")
    if evidence["candidate_metadata"]["sha256"]!="30b6bdf2a6cb2d60e2be36d4db1e124d71504393081b229e6d94da7e70322cbc": raise ValueError("candidate metadata hash mismatch")
    e3=json.loads((ROOT/FILES["e3_extraction"]).read_text()); e4=json.loads((ROOT/FILES["e4"]).read_text()); e5=json.loads((ROOT/FILES["e5"]).read_text()); e6=json.loads((ROOT/FILES["e6"]).read_text()); e7=json.loads((ROOT/FILES["e7"]).read_text()); dmeta=json.loads((ROOT/"models/experiment_d/random_forest_rf_v2_runtime_metadata.json").read_text()); seal=json.loads((ROOT/FILES["final_test_seal"]).read_text()); frozen=frozen_baseline()
    checks={"candidate_hash":True,"candidate_not_active":e5["candidate"]["status"]=="CANDIDATE / NOT_ACTIVE","e3_84_to_78":e3["raw_header_count"]==84 and e3["adapter"]["output_feature_count"]==78,"e4_lineage_and_session_control":e4["status"]=="PASS_WITH_DOCUMENTED_LIMITATION" and e4["checks"]["duplicate_row_identity_count"]==0,"e5_frozen_parameters_and_feature_contract":e5["verdict"]=="PASS" and e5["candidate"]["n_features_in"]==78,"e6_frozen_validation":e6["status"]=="PASS_WITH_DOCUMENTED_LIMITATION","e7_new_runtime_validation":e7["status"]=="PASS_WITH_DOCUMENTED_LIMITATION","rf_v2_frozen_hashes":all(x["matches"] for x in frozen["entries"]),"final_test_seal":seal["status"]=="PASS","no_promotion_performed":True}
    if not all(checks.values()): raise ValueError(checks)
    rows=[]
    rows.append({"evidence_type":"historical sealed Experiment D evidence","dataset_or_scope":"D6 published RF-v2 baseline evidence","model":"rf-v2.0","accuracy":dmeta["metrics"]["accuracy"],"normal_recall":dmeta["metrics"]["classification_report"]["Normal"]["recall"],"ddos_recall":dmeta["metrics"]["classification_report"]["DDoS"]["recall"],"portscan_recall":dmeta["metrics"]["classification_report"]["PortScan"]["recall"],"interpretation":"Historical reference only; not reused for Experiment E model selection."})
    for name,source in (("E6 offline validation",e6),("E7 unseen 3-VM runtime validation",e7)):
        for model,key in (("rf-v2.0","rf_v2"),("rf-v3.0-candidate","rf_v3_candidate")):
            r=source[key]; rows.append({"evidence_type":name,"dataset_or_scope":"new Experiment E held-out validation" if name.startswith("E6") else "new preregistered 3-VM PCAPs","model":model,"accuracy":r["accuracy"],"normal_recall":m(r,"Normal")["recall"],"ddos_recall":None,"portscan_recall":m(r,"PortScan")["recall"],"portscan_false_negatives":r.get("portscan_false_negative_count",r.get("portscan_false_negatives")),"normal_to_portscan_false_positives":r.get("normal_false_positive_as_portscan_count",r.get("normal_to_portscan_false_positives")),"interpretation":"Direct, same-row model comparison; no DDoS ground truth."})
    prob={"e6_p_v1_portscan_probability_mean":{"rf_v2":e6["rf_v2"]["session_results"]["P-V1"]["probability_summary"]["PortScan"]["mean"],"rf_v3":e6["rf_v3_candidate"]["session_results"]["P-V1"]["probability_summary"]["PortScan"]["mean"]},"e7_p_r1_portscan_probability_mean":{"rf_v2":e7["rf_v2"]["sessions"]["E7-P-R1"]["probability_summary"]["PortScan"]["mean"],"rf_v3":e7["rf_v3_candidate"]["sessions"]["E7-P-R1"]["probability_summary"]["PortScan"]["mean"]}}
    conclusion={"scientific_question":"Did controlled Experiment E adaptation improve PortScan generalization to the new 3-VM runtime distribution?","answer":"Yes, for the observed PortScan and Normal scenarios.","e6_portscan_recall_delta":m(e6["rf_v3_candidate"],"PortScan")["recall"]-m(e6["rf_v2"],"PortScan")["recall"],"e6_false_negative_reduction":e6["rf_v2"]["portscan_false_negative_count"]-e6["rf_v3_candidate"]["portscan_false_negative_count"],"e7_portscan_recall_delta":m(e7["rf_v3_candidate"],"PortScan")["recall"]-m(e7["rf_v2"],"PortScan")["recall"],"e7_false_negative_reduction":e7["rf_v2"]["portscan_false_negatives"]-e7["rf_v3_candidate"]["portscan_false_negatives"],"normal_recall_preserved_in_e6_and_e7":True,"probability_shift":prob,"consistency":"RF-v2 PortScan recall was 0.0 in E6 and E7; RF-v3 was 0.999334 in E6 and 0.998336 in the distinct E7 live topology."}
    decision="MORE_VALIDATION_REQUIRED"
    comparison={"schema":"experiment_e_e8_final_comparison","status":"PASS_WITH_DOCUMENTED_LIMITATION","decision":decision,"scope":"Scientific decision only; no model promotion, activation, retraining, tuning, or final-test access.","evidence_role_separation":{"historical":"Experiment D sealed RF-v2 results are background/baseline evidence only.","adaptation_training":"E4 controlled, session-aware E5 training data; not performance evidence.","validation":"E6 untouched N-V1/P-V1 same-row comparison.","unseen_runtime":"E7 preregistered new 3-VM PCAP comparison."},"comparison_rows":rows,"conclusion":conclusion,"limitations":["Experiment E does not validate DDoS runtime recall because no new DDoS validation/runtime session exists.","Experiment E Normal validation is small (17 E6 rows; 25 E7 flows).","E7 is minimal one-session-per-observed-class runtime evidence.","RF-v3 is not established as universally superior across attacks, topologies, or operating conditions."],"e9_promotion_scientifically_authorized":False,"evidence":evidence,"integrity_checks":checks}
    write_new(OUT,comparison)
    audit={"schema":"experiment_e_e8_scientific_decision","status":"PASS_WITH_DOCUMENTED_LIMITATION","decision":decision,"recommendation":"The candidate is scientifically supported for the narrow PortScan remediation finding, but broad three-class promotion requires new DDoS runtime validation and broader Normal/runtime replication.","e9_promotion_scientifically_authorized":False,"comparison_path":str(OUT.relative_to(ROOT)),"comparison_sha256":sha256_file(OUT),"integrity_checks":checks,"final_test_policy":"No final-test content was read; sealed Experiment D results were referenced only through previously published runtime metadata and frozen manifests."}
    write_new(AUDIT,audit); print(json.dumps({"verdict":comparison["status"],"decision":decision,"e9_authorized":False}))
if __name__=="__main__": main()
